import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {migrate,act,validate,question,balances,report,liquidationSteps} from './dist/demo/engine.js';
import {storyMoment} from './dist/demo/timeline.js';
import {dueAmount} from './dist/demo/course.js';

// These deterministic snapshots were generated by the published v27 engine,
// commit 86286b5ff8f8e8f35a1ecaedac74a3e9382b993c, without user data.
const fixtures=JSON.parse(readFileSync('fixtures/course-v27.json','utf8'));
for(const old of fixtures){
 const journal=JSON.stringify(old.tx),s=migrate({...old,course:{...old.course,totalWeeks:4}}),knownContracts=structuredClone(old.course.contracts);
 assert.equal(JSON.stringify(s.tx),journal);assert.deepEqual(s.course.contracts,knownContracts);if(old.pendingBook){assert.equal(s.pendingBook.id,old.pendingBook.id);assert.equal(s.pendingBook.statementVersion,4);for(const field of old.pendingBook.fields){const kept=s.pendingBook.fields.find(f=>f.page===field.page&&f.key===field.key&&f.target===field.target);if(kept)assert.equal(kept.value,field.value);}}else assert.equal(s.pendingBook,null);
 const originalIds=new Map(s.tx.map(t=>[t.id,JSON.stringify(t)]));let stopped=false;
 for(let guard=0;guard<240;guard++){
  validate(s);assert.deepEqual(migrate(JSON.parse(JSON.stringify(s))),s);
  if(['courseSummary','results'].includes(s.stage)&&!s.pendingBook){stopped=true;break;}
  const before=storyMoment(s);let action,value;const p=s.pendingBook,q=question(s);
  if(p){if(!p.checked){for(const f of p.fields)f.value=String(f.target/100);assert.ok(act(s,'book-check'));}p.seenPages=[...p.pages];action='book-done';}
  else if(q){if(!s.lessonsSeen[s.stage])act(s,'learn');act(s,'pick',q.correct);act(s,'answer',q.correct);action='next';}
  else if(['weekBills','weekLoan'].includes(s.stage)&&balances(s).cash<dueAmount(s)){
   if(s.course.contracts.some(v=>v.balance&&!v.advanceTried))action='course-advance';
   else if(balances(s).inventory)action='course-clear';
   else{action='liquidate';value='failure';}
  }else{
   action=({rainDay:'rain-close',weekRest:'week-rest-close',weekOffer:'course-offer',weekSale:'course-close',weekSummary:s.course.week<4?'next-week':'keep-course',weekStart:'week-open',dailyTrading:'skip-day',dailyOpen:'daily-trade',dailyReady:'daily-trade',dailySold:'daily-close',weekBills:'course-pay-supplier',weekLoan:'course-pay-loan',weekCollect:'course-collect',liquidation:'settle'})[s.stage];
   value=s.stage==='weekOffer'?'bulk':s.stage==='liquidation'?s.liquidation.step:undefined;
  }
  assert.ok(action,s.stage);assert.ok(act(s,action,value));const after=storyMoment(s);assert.ok(after.day*1440+after.minute>=before.day*1440+before.minute,`${old.stage}: ${action} went backward`);
 }
 assert.ok(stopped,old.stage);assert.equal(s.stage,'courseSummary');assert.equal(s.day,28);assert.equal(balances(s).payable,0);assert.equal(balances(s).interestPayable,0);
 for(const [id,json] of originalIds)assert.equal(JSON.stringify(s.tx.find(t=>t.id===id)),json,'posted old transactions must remain byte-for-byte unchanged');
 const priorGroup=old.tx.find(t=>t.id==='w3-sale');if(priorGroup){const kept=s.tx.find(t=>t.id==='w3-sale');assert.equal(kept.revenue,kept.quantity*600);assert.equal(kept.delta.receivable,priorGroup.delta.receivable);assert.ok(s.tx.some(t=>t.id==='w3-sale-collection'||t.id==='w3-sale-advance'));}
 assert.equal(report(s).assets,report(s).liabilities+report(s).equity);
}
console.log('Published v27 migration: unchosen offer becomes cash bulk pricing; posted 6-yuan credit orders, pending drafts, dates and amounts remain unchanged; all four snapshots finish daily without time reversal, duplicate depreciation or unpaid due debt.');
